// Attribute bytes in built chunks to source modules using source maps.
//
//   bunx vite build --sourcemap --outDir temp/perf/build-sm --emptyOutDir
//   bun bench/bundle-attribution.ts [buildDir] [--entry-only] [--top N]
//
// Prints JSON: per chunk, its raw and gzip size and the top source modules by
// generated bytes. With --entry-only it reports the chunk loaded by index.html
// plus its static imports (the critical path).
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { join, basename } from 'node:path';
import { gzipSync } from 'node:zlib';

const args = process.argv.slice(2);
const dir = args.find((arg) => !arg.startsWith('--')) ?? 'temp/perf/build-sm';
const entryOnly = args.includes('--entry-only');
const topIndex = args.indexOf('--top');
const top = topIndex >= 0 ? Number(args[topIndex + 1]) : 15;
const assets = join(dir, 'assets');

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64_INDEX = new Map([...B64].map((char, index) => [char, index]));

function decodeSegment(segment: string): number[] {
  const out: number[] = [];
  let value = 0;
  let shift = 0;
  for (const char of segment) {
    const digit = B64_INDEX.get(char) ?? 0;
    value += (digit & 31) << shift;
    if (digit & 32) {
      shift += 5;
    } else {
      out.push(value & 1 ? -(value >>> 1) : value >>> 1);
      value = 0;
      shift = 0;
    }
  }
  return out;
}

function attribute(code: string, map: { sources: string[]; mappings: string }): Map<string, number> {
  const lines = code.split('\n');
  const bytes = new Map<string, number>();
  let source = 0;
  const mapLines = map.mappings.split(';');
  for (let line = 0; line < mapLines.length && line < lines.length; line += 1) {
    const text = lines[line];
    const segments = mapLines[line] ? mapLines[line].split(',') : [];
    let column = 0;
    const marks: { column: number; source: number }[] = [];
    for (const segment of segments) {
      const fields = decodeSegment(segment);
      column += fields[0] ?? 0;
      if (fields.length >= 4) source += fields[1];
      marks.push({ column, source: fields.length >= 4 ? source : -1 });
    }
    for (let index = 0; index < marks.length; index += 1) {
      const end = index + 1 < marks.length ? marks[index + 1].column : text.length;
      const length = Math.max(0, end - marks[index].column);
      const name = marks[index].source >= 0 ? map.sources[marks[index].source] : '(unmapped)';
      bytes.set(name, (bytes.get(name) ?? 0) + length);
    }
    if (!marks.length) bytes.set('(unmapped)', (bytes.get('(unmapped)') ?? 0) + text.length);
  }
  return bytes;
}

function normalize(source: string): string {
  const clean = source.replace(/\\/g, '/').replace(/^(\.\.\/)+/, '');
  const nm = clean.lastIndexOf('node_modules/');
  if (nm >= 0) {
    const rest = clean.slice(nm + 'node_modules/'.length).split('/');
    return 'npm:' + (rest[0].startsWith('@') ? rest.slice(0, 2).join('/') : rest[0]);
  }
  return clean;
}

function staticImports(code: string): string[] {
  const found = new Set<string>();
  for (const match of code.matchAll(/(?:^|[;}\s])import\s*(?:[\w$*{}\s,]+from\s*)?["']\.\/([^"']+\.js)["']/g)) found.add(match[1]);
  return [...found];
}

function chunkReport(file: string) {
  const path = join(assets, file);
  const code = readFileSync(path, 'utf8');
  const mapPath = path + '.map';
  const report: Record<string, unknown> = {
    chunk: file,
    rawKB: +(code.length / 1024).toFixed(1),
    gzipKB: +(gzipSync(code).length / 1024).toFixed(1),
  };
  if (existsSync(mapPath)) {
    const map = JSON.parse(readFileSync(mapPath, 'utf8'));
    const bytes = attribute(code, map);
    const grouped = new Map<string, number>();
    for (const [source, size] of bytes) grouped.set(normalize(source), (grouped.get(normalize(source)) ?? 0) + size);
    report.modules = [...grouped].sort((a, b) => b[1] - a[1]).slice(0, top)
      .map(([module, size]) => ({ module, rawKB: +(size / 1024).toFixed(1), share: +(size / code.length).toFixed(3) }));
  }
  report.staticImports = staticImports(code);
  return report;
}

const html = readFileSync(join(dir, 'index.html'), 'utf8');
const entry = /src="\.\/assets\/([^"]+\.js)"/.exec(html)?.[1];
let files: string[];
if (entryOnly && entry) {
  const seen = new Set<string>();
  const queue = [entry];
  while (queue.length) {
    const next = queue.shift()!;
    if (seen.has(next)) continue;
    seen.add(next);
    queue.push(...staticImports(readFileSync(join(assets, next), 'utf8')));
  }
  files = [...seen];
} else {
  files = readdirSync(assets).filter((file) => file.endsWith('.js'));
}
const chunks = files.map(chunkReport).sort((a, b) => (b.gzipKB as number) - (a.gzipKB as number));
console.log(JSON.stringify({ dir, entry: entry ? basename(entry) : null, criticalPath: entryOnly, chunks }, null, 2));
